css:
.mtdr { font-family: Arial, Helvetica, sans-serif; font-size: 9pt; color: #000; }
.mtdr h1 { font-size: 15pt; margin: 0 0 4px; }
.mtdr h2 { font-size: 10.5pt; margin: 10px 0 3px; border-bottom: 1px solid #555; padding-bottom: 1px; }
.mtdr table { width: 100%; border-collapse: collapse; margin-bottom: 4px; }
.mtdr th, .mtdr td { border: 1px solid #bbb; padding: 2px 4px; vertical-align: top; }
.mtdr th { background: #eee; text-align: left; }
.mtdr .r { text-align: right; white-space: nowrap; }
.mtdr .kpi td { width: 25%; }
.mtdr .muted { color: #555; }
.mtdr .sign td { height: 34px; }
.mtdr .page { page-break-inside: avoid; }

html:
{%- set r = mobile_day_report(doc.mobile_trip) -%}
{%- set t = r.trip -%}{%- set s = r.summary -%}
{%- set cur = {"fieldtype": "Currency", "options": frappe.db.get_value("Company", doc.company, "default_currency")} -%}
{%- macro m(v) %}{{ frappe.format(v or 0, cur) }}{% endmacro -%}
{%- macro q(v) %}{{ frappe.format(v or 0, {"fieldtype": "Float"}) }}{% endmacro -%}
<div class="mtdr">
	<h1>{{ _("Mobile Trip Day Report") }} · {{ t.name }}</h1>
	<table>
		<tr><th>{{ _("Agent") }}</th><td>{{ t.agent_name }} ({{ t.agent }})</td><th>{{ _("Date") }}</th><td>{{ frappe.format(t.trip_date, "Date") }}</td></tr>
		<tr><th>{{ _("Vehicle / helper") }}</th><td>{{ t.vehicle or "" }}{% if t.helper %} · {{ t.helper }}{% endif %}</td><th>{{ _("Route") }}</th><td>{{ t.route or "" }}</td></tr>
		<tr><th>{{ _("First / last visit") }}</th><td>{{ r.first_visit or "-" }} – {{ r.last_visit or "-" }}</td><th>{{ _("Settlement") }}</th><td>{{ doc.name }} · {{ doc.workflow_state }}</td></tr>
	</table>

	<h2>{{ _("Day KPIs") }}</h2>
	<table class="kpi">
		<tr><td>{{ _("Planned") }}: <b>{{ s.planned_visits }}</b></td><td>{{ _("Visited") }}: <b>{{ s.visits }}</b></td><td>{{ _("Missed") }}: <b>{{ s.missed }}</b></td><td>{{ _("Off route") }}: <b>{{ s.off_route }}</b></td></tr>
		<tr><td>{{ _("Sales visits") }}: <b>{{ s.sales_visits }}</b></td><td>{{ _("No sale") }}: <b>{{ s.no_sale_visits }}</b></td><td>{{ _("Strike rate") }}: <b>{{ r.strike_rate }}%</b></td><td>{{ _("Invoices") }}: <b>{{ s.invoices }}</b></td></tr>
		<tr><td>{{ _("Net sales") }}: <b>{{ m(s.net_sales) }}</b></td><td>{{ _("Invoice total") }}: <b>{{ m(s.sales_total) }}</b></td><td>{{ _("Cash collected") }}: <b>{{ m(s.cash_collected) }}</b></td><td>{{ _("Credit given") }}: <b>{{ m(s.credit_given) }}</b></td></tr>
		<tr><td>{{ _("Customer returns") }}: <b>{{ m(s.return_value) }}</b></td><td>{{ _("Credit applied") }}: <b>{{ m(s.credit_applied) }}</b></td><td>{{ _("Line discounts") }}: <b>{{ m(s.line_discount) }}</b></td><td>{{ _("Invoice discounts") }}: <b>{{ m(s.invoice_discount) }}</b></td></tr>
	</table>

	<h2>{{ _("Visit log") }}</h2>
	<table>
		<tr><th>{{ _("Time") }}</th><th>{{ _("Customer") }}</th><th>{{ _("Outcome") }}</th><th>{{ _("Reason / remarks") }}</th><th>{{ _("Invoice") }}</th><th class="r">{{ _("Amount") }}</th><th class="r">{{ _("Collected") }}</th><th class="r">{{ _("Returns") }}</th><th>{{ _("Map") }}</th></tr>
		{%- for v in r.visit_log %}
		<tr><td>{{ v.time }}</td><td>{{ v.customer }}</td><td>{{ _(v.outcome) }}{% if v.off_route %} <span class="muted">({{ _("off route") }})</span>{% endif %}</td><td>{{ v.reason or "" }}{% if v.remarks %} {{ v.remarks }}{% endif %}</td><td>{{ v.invoice or "" }}</td><td class="r">{{ m(v.amount) }}</td><td class="r">{{ m(v.collected) }}</td><td class="r">{{ m(v.returns) }}</td><td>{% if v.map %}<a href="{{ v.map }}">{{ _("map") }}</a>{% endif %}</td></tr>
		{%- endfor %}
	</table>

	{%- if r.missed %}
	<h2>{{ _("Missed customers") }}</h2>
	<table><tr><th>{{ _("Seq") }}</th><th>{{ _("Customer") }}</th><th>{{ _("Frequency") }}</th></tr>
		{%- for x in r.missed %}<tr><td>{{ x.sequence }}</td><td>{{ x.customer_name or x.customer }}</td><td>{{ _(x.visit_frequency) }} {{ _(x.visit_day) if x.visit_day else "" }}</td></tr>{% endfor %}
	</table>
	{%- endif %}

	{%- if r.changes %}
	<h2>{{ _("Customer updates") }}</h2>
	<table><tr><th>{{ _("Customer") }}</th><th>{{ _("Field") }}</th><th>{{ _("Old") }}</th><th>{{ _("New") }}</th><th>{{ _("Status") }}</th></tr>
		{%- for c in r.changes %}<tr><td>{{ c.customer }}</td><td>{{ c.field }}</td><td>{{ c.old or "" }}</td><td>{{ c.new or "" }}</td><td>{{ _(c.status) if c.status else "" }}</td></tr>{% endfor %}
	</table>
	{%- endif %}

	{%- if r.shelf %}
	<h2>{{ _("Customer shelf stock") }}</h2>
	<table><tr><th>{{ _("Customer") }}</th><th>{{ _("Item") }}</th><th class="r">{{ _("Qty") }}</th><th>{{ _("Expiry") }}</th><th>{{ _("Competitor") }}</th></tr>
		{%- for x in r.shelf %}<tr><td>{{ x.customer }}</td><td>{{ x.item }}</td><td class="r">{{ q(x.qty) }} {{ x.uom or "" }}</td><td>{{ frappe.format(x.expiry, "Date") if x.expiry else "" }}</td><td>{{ x.competitor or "" }}</td></tr>{% endfor %}
	</table>
	{%- endif %}

	<h2>{{ _("Sales by invoice") }}</h2>
	<table><tr><th>{{ _("Invoice") }}</th><th>{{ _("Customer") }}</th><th class="r">{{ _("Net") }}</th><th class="r">{{ _("Tax") }}</th><th class="r">{{ _("Total") }}</th><th class="r">{{ _("Return credit") }}</th><th class="r">{{ _("Paid (cash)") }}</th><th class="r">{{ _("Outstanding") }}</th></tr>
		{%- for i in r.invoices %}<tr><td>{{ i.invoice }}</td><td>{{ i.customer }}</td><td class="r">{{ m(i.net) }}</td><td class="r">{{ m(i.tax) }}</td><td class="r">{{ m(i.total) }}</td><td class="r">{{ m(i.credit) }}</td><td class="r">{{ m(i.paid) }}</td><td class="r">{{ m(i.outstanding) }}</td></tr>{% endfor %}
	</table>

	<h2>{{ _("Sales by item") }}</h2>
	<table><tr><th>{{ _("Item") }}</th><th class="r">{{ _("Qty") }}</th><th class="r">{{ _("Amount") }}</th><th class="r">{{ _("Avg rate") }}</th><th class="r">{{ _("Discount (list − rate)") }}</th></tr>
		{%- for x in r.sales_items %}<tr><td>{{ x.item_name or x.item }}</td><td class="r">{{ q(x.qty) }} {{ x.uom }}</td><td class="r">{{ m(x.amount) }}</td><td class="r">{{ m(x.rate) }}</td><td class="r">{{ m(x.discount) }}</td></tr>{% endfor %}
	</table>

	<h2>{{ _("Collections") }}</h2>
	<table><tr><th>{{ _("Payment") }}</th><th>{{ _("Customer") }}</th><th>{{ _("Against") }}</th><th>{{ _("Mode") }}</th><th class="r">{{ _("Amount") }}</th></tr>
		{%- for c in r.collections %}<tr><td>{{ c.payment }}</td><td>{{ c.customer }}</td><td>{{ c.against }} {{ c.invoice or "" }}</td><td>{{ c.mode or "" }}</td><td class="r">{{ m(c.amount) }}</td></tr>{% endfor %}
	</table>

	{%- set rets = r.returns | selectattr("visit") | list %}
	{%- if rets %}
	<h2>{{ _("Customer returns") }}</h2>
	<table><tr><th>{{ _("Customer") }}</th><th>{{ _("Item") }}</th><th class="r">{{ _("Qty") }}</th><th>{{ _("Reason / condition") }}</th><th>{{ _("Against") }}</th><th>{{ _("Credit note") }}</th><th>{{ _("Credit applied to") }}</th><th class="r">{{ _("Credit") }}</th></tr>
		{%- for x in rets %}<tr><td>{{ x.customer_name or x.customer }}</td><td>{{ x.item_name or x.item_code }}</td><td class="r">{{ q(x.qty) }} {{ x.uom }}</td><td>{{ x.reason }} · {{ _(x.condition) if x.condition else "" }}{% if x.remarks %} · {{ x.remarks }}{% endif %}</td><td>{{ x.against_invoice or "" }}</td><td>{{ x.credit_note or "" }}</td><td>{{ x.credit_applied or "" }}</td><td class="r">{{ m(x.amount) }}</td></tr>{% endfor %}
	</table>
	{%- endif %}

	<h2>{{ _("Stock reconciliation") }}</h2>
	<table><tr><th>{{ _("Item") }}</th><th class="r">{{ _("Issued") }}</th><th class="r">{{ _("Top-up") }}</th><th class="r">{{ _("Sold") }}</th><th class="r">{{ _("Returned") }}</th><th class="r">{{ _("Damaged") }}</th><th class="r">{{ _("Missing") }}</th><th class="r">{{ _("Missing value") }}</th></tr>
		{%- for x in r.stock %}<tr><td>{{ x.item_name or x.item }} ({{ x.uom }})</td><td class="r">{{ q(x.issued) }}</td><td class="r">{{ q(x.topped_up) }}</td><td class="r">{{ q(x.sold) }}</td><td class="r">{{ q(x.returned) }}</td><td class="r">{{ q(x.damaged) }}</td><td class="r">{{ q(x.missing) }}</td><td class="r">{{ m(x.missing_value) }}</td></tr>{% endfor %}
	</table>
	{%- if doc.return_lines %}
	<table><tr><th>{{ _("Customer returns counted") }}</th><th class="r">{{ _("Credited") }}</th><th class="r">{{ _("Received") }}</th><th class="r">{{ _("Damaged") }}</th><th class="r">{{ _("Missing") }}</th></tr>
		{%- for x in doc.return_lines %}<tr><td>{{ x.item_name or x.item_code }} ({{ x.uom }})</td><td class="r">{{ q(x.credited_qty) }}</td><td class="r">{{ q(x.received_qty) }}</td><td class="r">{{ q(x.damaged_qty) }}</td><td class="r">{{ q(x.missing_qty) }}</td></tr>{% endfor %}
	</table>
	{%- endif %}

	<h2>{{ _("Cash reconciliation") }}</h2>
	{%- set c = r.cash %}
	<table>
		<tr><th>{{ _("Opening float") }}</th><td class="r">{{ m(c.opening) }}</td><th>{{ _("Cash collected") }}</th><td class="r">{{ m(c.collected) }}</td><th>{{ _("Expected") }}</th><td class="r">{{ m(c.expected) }}</td></tr>
		<tr><th>{{ _("Handed over") }}</th><td class="r">{{ m(c.handed_over) }}</td><th>{{ _("Variance") }}</th><td class="r">{{ m(c.variance) }}</td><th>{{ _("Action") }}</th><td>{{ _(c.action) if c.action else "" }}</td></tr>
	</table>
	{%- if c.denominations or c.cheques %}
	<table><tr><th>{{ _("Denomination / cheque") }}</th><th class="r">{{ _("Count") }}</th><th class="r">{{ _("Amount") }}</th></tr>
		{%- for d in c.denominations %}<tr><td>{{ m(d.denomination) }}</td><td class="r">{{ d.count }}</td><td class="r">{{ m(d.amount) }}</td></tr>{% endfor %}
		{%- for ch in c.cheques %}<tr><td>{{ _("Cheque") }} {{ ch.cheque_no }} ({{ ch.payment_entry }})</td><td></td><td class="r">{{ m(ch.amount) }}</td></tr>{% endfor %}
	</table>
	{%- endif %}

	<h2>{{ _("Sign-off") }}</h2>
	<table class="sign"><tr><th>{{ _("Step") }}</th><th>{{ _("By") }}</th><th>{{ _("Date / time") }}</th><th>{{ _("Signature") }}</th></tr>
		{%- for x in r.signoff %}<tr><td>{{ x.step }}</td><td>{{ x.full_name }}</td><td>{{ frappe.format(x.at, "Datetime") }}</td><td></td></tr>{% endfor %}
		{%- if not r.signoff %}<tr><td colspan="4" class="muted">{{ _("Not yet signed off.") }}</td></tr>{% endif %}
	</table>
</div>
